//! Reader assertions on the same immutable receipts generated by the L1d PostgreSQL proof.
use crate::ops_content_lens::{
    LensDefinitionError, PageRequest, SnapshotLookup, publications, read_snapshot, spot_check,
};
use linggan_storage_postgres::Database;
use serde_json::{Value, json};
use uuid::Uuid;

pub(super) async fn verify_reads(db: &Database, old: Uuid, latest: Uuid, dated: Uuid) {
    let load =
        |query: Value| read_snapshot(db, serde_json::from_value::<SnapshotLookup>(query).unwrap());
    let body = load(json!({"snapshotRef":old}))
        .await
        .unwrap()
        .snapshot
        .unwrap();
    assert_eq!(body["snapshotRef"], old.to_string());
    assert_eq!(
        load(json!({})).await.unwrap().snapshot.unwrap()["snapshotRef"],
        latest.to_string()
    );
    assert_eq!(
        load(json!({"from":"2026-11-02"}))
            .await
            .unwrap()
            .snapshot
            .unwrap()["snapshotRef"],
        dated.to_string()
    );
    assert!(
        load(json!({"from":"2026-11-03"}))
            .await
            .unwrap()
            .snapshot
            .is_none()
    );
    assert!(matches!(
        load(json!({"snapshotRef":Uuid::new_v4()})).await,
        Err(LensDefinitionError::SnapshotNotFound)
    ));
    assert!(matches!(
        load(json!({"snapshotRef":old,"to":"2026-11-02"})).await,
        Err(LensDefinitionError::InvalidScope)
    ));

    let page = |query: Value| {
        let mut query = query;
        query["snapshotRef"] = json!(old);
        publications(db, serde_json::from_value::<PageRequest>(query).unwrap())
    };
    let p1 = page(json!({"moment":"unclear","offer":"other","limit":1}))
        .await
        .unwrap();
    let p2 = page(json!({"moment":"unclear","offer":"other","limit":1,"offset":1}))
        .await
        .unwrap();
    assert_eq!((p1.total, p2.total), (2, 2));
    assert_ne!(p1.items[0].publication_ref, p2.items[0].publication_ref);
    assert_eq!(page(json!({"offset":2})).await.unwrap().items.len(), 0);
    assert_eq!(
        page(json!({"offer":"actionable_method"}))
            .await
            .unwrap()
            .total,
        0
    );
    for subset in ["numerator", "denominator"] {
        let p = page(json!({"metric":"overThousand","subset":subset,"offer":"other"}))
            .await
            .unwrap();
        assert_eq!(p.total, 1);
        assert_eq!(p.items[0].views, Some(1200));
        assert!(p.items[0].title.is_some());
    }
    assert_eq!(
        page(json!({"metric":"titledPublications"}))
            .await
            .unwrap()
            .total,
        2
    );
    assert_eq!(
        page(json!({"metric":"titledViews"})).await.unwrap().total,
        1
    );
    assert!(matches!(
        page(json!({"limit":0})).await,
        Err(LensDefinitionError::InvalidScope)
    ));
    let check = spot_check(db, latest).await.unwrap();
    assert_eq!(check.items.len(), 1);
    // The frozen effective offer was adjudicated to actionable_method; the sampled
    // primary's machine output remains "other" for both titles and both snapshots.
    assert_eq!(check.items[0].offer, "other");
    assert_eq!(check.items[0].moment, "other");
    assert!(check.items[0].title.is_some());

    // A snapshot that was fresh on its original read day can be stale today.
    let historical:Uuid=sqlx::query_scalar("INSERT INTO linggan_ops_lens_snapshot
        (snapshot_ref,as_of,taxonomy_ref,metric_ref,input_hash,analysis_input,body)
        SELECT gen_random_uuid(),date '2000-01-02',taxonomy_ref,metric_ref,repeat('d',64),analysis_input,
          jsonb_set(jsonb_set(jsonb_set(body,'{quality,latestPublishedDate}',to_jsonb('2000-01-01'::text)),'{quality,isStale}','false'),'{quality,staleDays}','1')
        FROM linggan_ops_lens_snapshot WHERE snapshot_ref=$1 RETURNING snapshot_ref")
        .bind(old).fetch_one(db.pool()).await.unwrap();
    let historical = load(json!({"snapshotRef":historical})).await.unwrap();
    assert_eq!(historical.snapshot.unwrap()["quality"]["isStale"], false);
    assert_eq!(historical.freshness.unwrap().is_stale, Some(true));

    // A new ledger title must not appear next to the old title's frozen machine labels.
    sqlx::raw_sql("INSERT INTO linggan_ops_native_write_request(request_ref,command_kind,actor_member_ref,payload_sha256,outcome,record_ref,resulting_version,outcome_code)
      SELECT md5('retitle'||n)::uuid,'publication_create',md5('snapshot-member')::uuid,decode(repeat('00',32),'hex'),'accepted',md5('pub'||n)::uuid,1,'saved' FROM generate_series(1,2)n;
      INSERT INTO linggan_ops_publication_field_adoption(adoption_ref,publication_ref,publication_version,field_name,disposition,source_kind,source_request_ref,value_text,observed_at)
      SELECT gen_random_uuid(),md5('pub'||n)::uuid,1,'title','adopted','native_registration',md5('retitle'||n)::uuid,'新标题',scope_001_now()::text FROM generate_series(1,2)n")
        .execute(db.pool()).await.unwrap();
    assert!(spot_check(db, old).await.unwrap().items[0].title.is_none());
    assert_eq!(
        page(json!({})).await.unwrap().items[0].title.as_deref(),
        Some("新标题")
    );
}
